 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = [[grid[r][c] != background for c in range(w)] for r in range(h)]

    # Connect consecutive marker cells in each row and column.
    for r in range(h):
        cols = [c for c in range(w) if markers[r][c]]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if markers[r][c]]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
